// Extract the embedding from OpenAI response
// and prepare the payload for hybrid search
const embeddingResponse = $input.first().json;
const triggerData = $('When Executed by Another Workflow').first().json;
// Get the embedding vector
const queryEmbedding = embeddingResponse.data[0].embedding;
// Extract weights from trigger data (set by AI agent)
const vectorWeight = triggerData.vector_weight ?? 1.0;
const keywordWeight = triggerData.keyword_weight ?? 1.0;
const ilikeWeight = triggerData.ilike_weight ?? 0.5;
// Extract price filters (convert string 'null' to actual null)
const minPrice = triggerData.min_price && triggerData.min_price !== 'null' 
  ? Number(triggerData.min_price) 
  : null;
const maxPrice = triggerData.max_price && triggerData.max_price !== 'null' 
  ? Number(triggerData.max_price) 
  : null;
// Extract NEW filters
const inStockOnly = triggerData.in_stock_only === true 
  || triggerData.in_stock_only === 'true';
const categoryFilter = triggerData.category_filter 
  && triggerData.category_filter !== 'null'
  && triggerData.category_filter !== ''
  ? triggerData.category_filter 
  : null;
const sortBy = triggerData.sort_by 
  && triggerData.sort_by !== 'null'
  && triggerData.sort_by !== ''
  ? triggerData.sort_by 
  : null;

// Build the payload for the edge function
const payload = {
  query: triggerData.query,
  query_embedding: queryEmbedding,
  match_count: triggerData.match_count ?? 10,
  rrf_k: triggerData.rrf_k ?? 60,
  vector_weight: vectorWeight,
  keyword_weight: keywordWeight,
  ilike_weight: ilikeWeight,
  metadata_filter: triggerData.metadata_filter ?? null,
  min_price: minPrice,
  max_price: maxPrice,
  in_stock_only: inStockOnly,
  category_filter: categoryFilter,
  sort_by: sortBy
};
return {
  json: payload
};

// Format the product search results for the AI agent

const response = $input.first().json;

if (!response.success) {
  return {
    json: {
      success: false,
      error: response.error || 'Search failed',
      products: []
    }
  };
}

// Format results for better AI consumption
const formattedProducts = response.results.map((result, index) => {
  const meta = result.metadata || {};
  return {
    rank: index + 1,
    product_id: result.id,
    name: meta.name,
    sku: meta.sku,
    price: meta.price,
    special_price: meta.special_price,
    in_stock: (meta.quantity || 0) > 0,
    quantity: meta.quantity,
    categories: meta.categories,
    attributes: meta.attributes,
    product_url: meta.product_url,
    description: result.content?.substring(0, 600),
    scores: {
      rrf_combined: result.rrf_score?.toFixed(4),
      vector_rank: result.vector_rank,
      keyword_rank: result.keyword_rank,
      ilike_rank: result.ilike_rank
    }
  };
});

return {
  json: {
    success: true,
    query: response.query,
    weights_used: response.weights_used,
    product_count: formattedProducts.length,
    products: formattedProducts,
    // Create a text summary for the AI
    summary: formattedProducts.map(p => 
      `[${p.rank}] ${p.name} - ${p.price} грн${p.special_price ? ` (акція: ${p.special_price} грн)` : ''} ${p.in_stock ? '✓ в наявності' : 'Будь ласка, наявність та вартість уточнюйте'}`
    ).join('\n')
  }
};
